<script setup lang="ts">
import { PhArchive, PhArrowDown, PhArrowUp, PhArrowUpRight, PhCheck, PhClockCounterClockwise, PhFunnel, PhHouse, PhJar, PhMagnifyingGlass, PhMinus, PhPlus, PhStack, PhX } from '@phosphor-icons/vue';
import { addBatch, addProduct, addZone, categories, demoPantry, emptyPantry, moveStock, productStock, setProductIcon, stock, units, type Batch, type Category, type Location, type Product, type Unit } from '../src/domain/pantry';
import { productIcons, iconLabels, resolveProductIcon, type ProductIconId } from '../src/domain/product-icons';
const { state, ready, busy, error, mutate } = usePantry();
const { locale, t, setLocale, languageError } = useLanguage();
const iconOptions = computed(() => productIcons.map(value => ({ value, label: t(iconLabels[value]) })));
const zoneName = ref(''); const zoneError = ref(''); const zoneNotice = ref(''); const showInlineZone = ref(false);
const zones = computed(() => state.value.zones);
function zoneLabel(id: string) { const zone = zones.value.find(item => item.id === id); return zone?.system ? t(zone.system) : zone?.name || id; }
function batchLabel(batch: Batch) { return batch.defaultLabel ? `${t('Lote')} ${batch.label.slice(5)}` : batch.label; }
async function createZone(forBatch = false) {
  zoneError.value = ''; zoneNotice.value = '';
  const ok = await mutate(current => addZone(current, zoneName.value));
  if (ok) { if (forBatch) form.location = state.value.zones.at(-1)!.id; zoneName.value = ''; showInlineZone.value = false; zoneNotice.value = forBatch ? 'Zona creada. La hemos seleccionado para este lote.' : 'Zona guardada. Ya puedes usarla en tus lotes.'; }
  else zoneError.value = error.value;
}
const view = ref<'inventory' | 'history' | 'zones'>('inventory');
const search = ref(''); const category = ref('Todas'); const location = ref('Todas'); const stockFilter = ref('Todos');
const modal = ref<'product' | 'batch' | 'movement' | 'detail' | 'reset' | 'icon' | null>(null);
const dialog = ref<HTMLDialogElement>(); const selectedId = ref(''); const notice = ref(''); const formError = ref('');
const form = reactive({ icon: 'auto' as ProductIconId, name: '', category: 'Conservas' as Category, unit: 'botes' as Unit, quantity: 1, label: '', location: 'Despensa' as Location, date: '', notes: '', batchId: '', movement: 'entrada' as 'entrada' | 'consumo' | 'ajuste', reason: '' });
const selected = computed(() => state.value.products.find(p => p.id === selectedId.value));
const batches = computed(() => state.value.batches.filter(b => b.productId === selectedId.value));
const availableBatches = computed(() => batches.value.filter(b => form.movement !== 'consumo' || stock(state.value, b.id) > 0));
const selectedBatch = computed(() => state.value.batches.find(b => b.id === form.batchId));
const currentStock = computed(() => selectedBatch.value ? stock(state.value, selectedBatch.value.id) : 0);
const normalize = (text: string) => text.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
const visibleProducts = computed(() => state.value.products.filter(p => {
  const productBatches = state.value.batches.filter(b => b.productId === p.id);
  return normalize(p.name).includes(normalize(search.value)) && (category.value === 'Todas' || p.category === category.value) && (location.value === 'Todas' || productBatches.some(b => b.location === location.value && stock(state.value, b.id) > 0)) && (stockFilter.value === 'Todos' || (stockFilter.value === 'Con existencias' ? productStock(state.value, p.id) > 0 : productStock(state.value, p.id) === 0));
}).sort((a,b) => a.name.localeCompare(b.name, locale.value)));
const activeBatches = computed(() => state.value.batches.filter(b => stock(state.value, b.id) > 0));
function activeBatchCount(productId: string) { return activeBatches.value.filter(batch => batch.productId === productId).length; }
function zoneBatchCount(zoneId: string) { return activeBatches.value.filter(batch => batch.location === zoneId).length; }
const activeLocations = computed(() => new Set(activeBatches.value.map(b => b.location)).size);
const history = computed(() => state.value.movements.map(m => { const batch = state.value.batches.find(b => b.id === m.batchId)!; return { ...m, batch, product: state.value.products.find(p => p.id === batch.productId)! }; }).filter(m => normalize(m.product.name + ' ' + m.batch.label).includes(normalize(search.value))));
const modalTitle = computed(() => ({ icon: t('Cambiar icono'), product: t("Un producto nuevo"), batch: t("Añadir un lote"), movement: form.movement === 'entrada' ? t("Añadir existencias") : form.movement === 'consumo' ? t("Registrar consumo") : t("Corregir recuento"), detail: selected.value?.name || t("Producto"), reset: t("Empezar mi despensa") })[modal.value || 'product']);
function closeModal() { if (!busy.value) modal.value = null; }
watch(modal, async value => { await nextTick(); if (value && !dialog.value?.open) { dialog.value?.showModal(); dialog.value?.querySelector<HTMLInputElement>('input:not([type="hidden"])')?.focus(); } else if (!value && dialog.value?.open) dialog.value.close(); });
function resetForm() { Object.assign(form, { icon: 'auto', name: '', category: 'Conservas', unit: 'botes', quantity: 1, label: '', location: 'Despensa', date: '', notes: '', batchId: '', movement: 'entrada', reason: '' }); formError.value = ''; zoneName.value = ''; zoneError.value = ''; zoneNotice.value = ''; showInlineZone.value = false; }
function openProduct() { resetForm(); form.quantity = 0; modal.value = 'product'; }
function openBatch(product: Product) { resetForm(); selectedId.value = product.id; modal.value = 'batch'; }
function openMovement(product: Product, type: 'entrada' | 'consumo' | 'ajuste', batchId?: string) {
  resetForm(); selectedId.value = product.id; form.movement = type;
  const list = state.value.batches.filter(b => b.productId === product.id && (type !== 'consumo' || stock(state.value,b.id) > 0));
  if (!list.length) { openBatch(product); return; }
  form.batchId = batchId || list[0]!.id; if(type === 'ajuste') form.quantity = stock(state.value,form.batchId); modal.value = 'movement';
}
function openIcon(product: Product) { resetForm(); selectedId.value = product.id; form.icon = product.icon || 'auto'; modal.value = 'icon'; }
function showDetail(product: Product) { selectedId.value = product.id; formError.value = ''; modal.value = 'detail'; }
function dateLabel(value: string) { return value ? new Intl.DateTimeFormat(locale.value, { day: 'numeric', month: 'short', year: 'numeric' }).format(new Date(value + 'T12:00:00')) : t("Sin fecha"); }
function timeLabel(value: string) { return new Intl.DateTimeFormat(locale.value, { day:'numeric',month:'short',hour:'2-digit',minute:'2-digit' }).format(new Date(value)); }
function productLocations(id: string) { return [...new Set(state.value.batches.filter(b=>b.productId===id&&stock(state.value,b.id)>0).map(b=>zoneLabel(b.location)))].join(' · ') || t('Sin existencias'); }
async function save() {
  formError.value = ''; let ok = false;
  if (modal.value === 'product') ok = await mutate(current => { let next = addProduct(current, form); if (form.quantity > 0) next = addBatch(next, next.products.at(-1)!.id, form); else if (!Number.isSafeInteger(form.quantity) || form.quantity !== 0) throw new Error('Introduce una cantidad entera válida.'); return next; });
  else if (modal.value === 'icon') ok = await mutate(current => setProductIcon(current, selectedId.value, form.icon));
  else if (modal.value === 'batch') ok = await mutate(current => addBatch(current, selectedId.value, form));
  else if (modal.value === 'movement') ok = await mutate(current => moveStock(current, form.batchId, form.movement, form.quantity, form.reason));
  else if (modal.value === 'reset') ok = await mutate(current => { if (!current.demo) throw new Error('Esta despensa ya no es de ejemplo. No se han borrado sus datos.'); return emptyPantry(); });
  if(ok) { notice.value = modal.value === 'reset' ? 'Tu despensa está lista para empezar.' : 'Cambio guardado en tu despensa.'; modal.value = null; } else formError.value = error.value;
}
async function loadDemo() { const ok = await mutate(current => { if(current.products.length) throw new Error('La despensa debe estar vacía para cargar el ejemplo.'); return demoPantry(); }); if(ok) notice.value='Ejemplo cargado. Puedes probar todas las acciones.'; }
function clearFilters() { search.value='';category.value='Todas';location.value='Todas';stockFilter.value='Todos'; }
</script>

<template>
  <div class="app-layout">
    <a class="skip-link" href="#main">{{ t("Saltar al contenido") }}</a>
    <aside class="sidebar">
      <a href="#main" class="brand" :aria-label="t('Rebost, inicio')" @click="view='inventory'"><span class="brand-symbol">r<span>.</span></span><span>rebost<span class="brand-caption">{{ t("un lugar para lo que guardas") }}</span></span></a>
      <div class="pantry-switch"><span class="pantry-avatar"><PhHouse :size="20" /></span><div><strong>{{ t("Mi despensa") }}</strong><span>{{ t("Tu espacio en casa") }}</span></div></div>
      <nav :aria-label="t('Navegación principal')" class="side-nav"><button :aria-current="view==='inventory'?'page':undefined" @click="view='inventory';search=''" type="button"><PhArchive :size="21" />{{ t("Mi despensa") }}<span class="nav-count">{{ state.products.length }}</span></button><button :aria-current="view==='history'?'page':undefined" @click="view='history';search=''" type="button"><PhClockCounterClockwise :size="21" />{{ t("Movimientos") }}</button><button :aria-current="view==='zones'?'page':undefined" @click="view='zones';zoneName='';zoneError='';zoneNotice=''" type="button"><PhHouse :size="21" />{{ t('Zonas') }}</button></nav>
      <div class="sidebar-note"><LlenguesPattern /><span class="tiny-label">{{ t("MENOS OLVIDOS, MÁS APROVECHAR") }}</span><p>{{ t("Cada bote cuenta.") }}<br />{{ t("Y cada pequeña reserva, también.") }}</p><PhJar :size="42" weight="duotone" /></div>
      <div class="local-indicator"><span class="local-dot" />{{ t("Guardado en este navegador") }}</div>
    </aside>
    <div class="main-column">
      <header class="topbar"><p><PhHouse :size="16" />{{ t("Mi despensa") }}<span>/</span>{{ view==='inventory'?t('Inventario'):view==='history'?t('Movimientos'):t('Zonas') }}</p><div class="topbar-tools"><label class="language-select"><span class="sr-only">{{ t('Idioma') }}</span><select :value="locale" :aria-label="t('Idioma')" @change="setLocale(($event.target as HTMLSelectElement).value)"><option value="es" lang="es">ES</option><option value="en" lang="en">EN</option><option value="ca" lang="ca">CA</option></select></label><span class="local-badge">{{ t("Primera versión · Local") }}</span></div></header>
      <main id="main" class="page-shell">
        <div class="page-heading"><LlenguesPattern /><div><p class="eyebrow">{{ t("UN POCO DE ORDEN, MUCHA TRANQUILIDAD") }}</p><h1>{{ view==='inventory'?t('Lo que tienes, a mano.'):view==='history'?t('Cada cambio, en su sitio.'):t('Una zona para cada reserva.') }}</h1><p class="page-intro">{{ view==='inventory'?t("Tus conservas, fermentados y básicos. Sabe qué queda y sigue disfrutándolo."):view==='history'?t('Una pequeña memoria de lo que entra, lo que utilizas y lo que corriges.'):t('Crea los espacios donde guardas tus productos y selecciónalos al añadir un lote.') }}</p></div><button v-if="view==='inventory'" class="button primary" :disabled="!ready||busy" @click="openProduct"><PhPlus :size="19" />{{ t("Añadir producto") }}</button></div>
        <p v-if="languageError" class="alert error" role="alert">{{ t(languageError) }}</p>
        <div v-if="error" class="alert error" role="alert">{{ t(error) }}</div>
        <div v-if="notice" class="notice" role="status"><PhCheck :size="18" />{{ t(notice) }}<button @click="notice=''" :aria-label="t('Cerrar aviso')"><PhX :size="17" /></button></div>
        <div v-if="state.demo" class="demo-banner"><div><strong>{{ t("Una despensa para probar.") }}</strong><span>{{ t("Son datos de ejemplo. Añade, consume y descubre cómo funciona.") }}</span></div><button class="text-button" :disabled="busy" @click="modal='reset'">{{ t("Empezar mi despensa") }}<PhArrowUpRight :size="17" /></button></div>
        <template v-if="view==='inventory'">
          <div class="stats-grid"><article class="stat"><span class="stat-icon"><PhJar :size="24" weight="duotone" /></span><div><strong>{{ state.products.length }}</strong><span>{{ t("productos en tu despensa") }}</span></div></article><article class="stat"><span class="stat-icon amber"><PhStack :size="24" weight="duotone" /></span><div><strong>{{ activeBatches.length }}</strong><span>{{ t("lotes con existencias") }}</span></div></article><article class="stat"><span class="stat-icon blue"><PhHouse :size="24" weight="duotone" /></span><div><strong>{{ activeLocations }}</strong><span>{{ t("ubicaciones con productos") }}</span></div></article></div>
          <div class="inventory-heading"><h2>{{ t("Tu inventario") }} <span>{{ visibleProducts.length }}</span></h2><label class="search"><PhMagnifyingGlass :size="19" /><input v-model="search" type="search" :placeholder="t('Buscar un producto…')" :aria-label="t('Buscar productos')" /></label></div>
          <div class="filters"><div class="category-tabs" :aria-label="t('Filtrar por categoría')"><button v-for="item in ['Todas',...categories]" :key="item" :aria-pressed="category===item" @click="category=item">{{ t(item) }}</button></div><div class="select-filters"><PhFunnel :size="16" aria-hidden="true" /><select v-model="location" :aria-label="t('Filtrar por ubicación')"><option value="Todas">{{ t("Todas las ubicaciones") }}</option><option v-for="zone in zones" :key="zone.id" :value="zone.id">{{ zoneLabel(zone.id) }}</option></select><select v-model="stockFilter" :aria-label="t('Filtrar por existencias')"><option value="Todos">{{ t("Todos") }}</option><option value="Con existencias">{{ t("Con existencias") }}</option><option value="Sin existencias">{{ t("Sin existencias") }}</option></select></div></div>
          <div v-if="!ready" class="empty-state"><span class="empty-icon"><PhArchive :size="38" /></span><h3>{{ error?t("Tu despensa no está disponible"):t("Preparando tu despensa…") }}</h3><p>{{ error?t("Revisa el aviso de arriba e inténtalo de nuevo."):t("Estamos leyendo los datos guardados en este navegador.") }}</p></div>
          <div v-else-if="!state.products.length" class="empty-state"><span class="empty-icon"><PhJar :size="43" weight="duotone" /></span><p class="eyebrow">{{ t("TODO EMPIEZA CON UN PRIMER BOTE") }}</p><h3>{{ t("Hagamos sitio a tu despensa.") }}</h3><p>{{ t("Añade lo que guardas en casa y registra tus lotes.") }}<br />{{ t("O descubre Rebost con una despensa de ejemplo.") }}</p><div class="empty-actions"><button class="button primary" @click="openProduct"><PhPlus :size="18" />{{ t("Añadir mi primer producto") }}</button><button class="button secondary" :disabled="busy" @click="loadDemo">{{ t("Probar con un ejemplo") }}<PhArrowUpRight :size="18" /></button></div></div>
          <div v-else-if="!visibleProducts.length" class="empty-state compact"><PhMagnifyingGlass :size="35" /><h3>{{ t("No encontramos productos.") }}</h3><p>{{ t("Prueba con otra búsqueda o cambia los filtros.") }}</p><button class="text-button" @click="clearFilters">{{ t("Limpiar filtros") }}</button></div>
          <div v-else class="product-grid"><article v-for="product in visibleProducts" :key="product.id" class="product-card"><div class="product-card-top"><span class="product-icon" :class="`category-${categories.indexOf(product.category)}`"><ProductIcon :name="resolveProductIcon(product)" /></span><span class="category-label">{{ t(product.category) }}</span></div><button class="product-title" @click="showDetail(product)">{{ product.name }}<PhArrowUpRight :size="17" /></button><p class="product-location"><PhHouse :size="14" />{{ productLocations(product.id) }}</p><div class="stock-line"><p><strong>{{ productStock(state,product.id) }}</strong> {{ t(product.unit) }}</p><span>{{ activeBatchCount(product.id) }} {{ t(activeBatchCount(product.id) === 1 ? 'lote activo' : 'lotes activos') }}</span></div><div class="card-actions"><button :disabled="busy" @click="openMovement(product,'entrada')"><PhPlus :size="17" />{{ t("Añadir") }}</button><button :disabled="busy||productStock(state,product.id)===0" @click="openMovement(product,'consumo')"><PhMinus :size="17" />{{ t("Consumir") }}</button></div></article><button class="add-card" @click="openProduct"><span><PhPlus :size="25" /></span><strong>{{ t("Algo más para guardar") }}</strong><span>{{ t("Añade otro producto a tu despensa") }}</span></button></div>
          <p v-if="state.products.length" class="inventory-note"><PhClockCounterClockwise :size="16" />{{ t("Cada entrada y consumo queda guardado en tus movimientos.") }}</p>
        </template>
        <template v-else-if="view==='history'"><div class="inventory-heading"><h2>{{ t("Historial") }} <span>{{ history.length }}</span></h2><label class="search"><PhMagnifyingGlass :size="19" /><input v-model="search" type="search" :placeholder="t('Buscar producto o lote…')" :aria-label="t('Buscar movimientos')" /></label></div><div v-if="!history.length" class="empty-state"><PhClockCounterClockwise :size="40" /><h3>{{ search?t("No hay coincidencias."):t("Aquí empieza la historia de tu despensa.") }}</h3><p>{{ t("Las entradas, consumos y correcciones aparecerán aquí.") }}</p></div><ol v-else class="history-list"><li v-for="movement in history" :key="movement.id"><span class="movement-icon" :class="movement.type"><PhArrowDown v-if="movement.delta>0" :size="21" /><PhArrowUp v-else :size="21" /></span><div class="movement-description"><strong>{{ movement.product.name }}</strong><p>{{ batchLabel(movement.batch) }} · {{ zoneLabel(movement.batch.location) }}</p><span v-if="movement.note">{{ movement.systemNote === 'batchAdded' ? t('Lote añadido') : movement.note }}</span></div><div class="movement-meta"><strong :class="movement.delta>0?'positive':'negative'">{{ movement.delta>0?'+':'' }}{{ movement.delta }} {{ t(movement.product.unit) }}</strong><span>{{ movement.type==='entrada'?t("Entrada"):movement.type==='consumo'?t("Consumo"):t("Corrección") }} · {{ timeLabel(movement.createdAt) }}</span></div></li></ol></template>
        <section v-else-if="view==='zones'" class="zones-section" :aria-label="t('Gestionar zonas')">
          <form class="zone-create" @submit.prevent="createZone()"><fieldset :disabled="!ready || busy"><label>{{ t('Nombre de la zona') }}<input v-model="zoneName" required maxlength="80" :placeholder="t('Ej. Despensa 1, Almacén 2')" /></label><button class="button primary" type="submit"><PhPlus :size="18" />{{ busy ? t('Guardando…') : t('Crear zona') }}</button></fieldset></form>
          <p v-if="zoneError" class="alert error" role="alert">{{ t(zoneError) }}</p>
          <p v-if="zoneNotice" class="notice" role="status">{{ t(zoneNotice) }}</p>
          <div class="zone-grid"><article v-for="zone in zones" :key="zone.id" class="zone-card"><PhHouse :size="27" weight="duotone" /><h2>{{ zoneLabel(zone.id) }}</h2><p>{{ zoneBatchCount(zone.id) }} {{ t(zoneBatchCount(zone.id) === 1 ? 'lote con existencias' : 'lotes con existencias') }}</p></article></div>
        </section>
        <footer class="page-footer"><span>rebost<span class="footer-dot">.</span> <span>{{ t("Un lugar para lo que guardas.") }}</span></span><p>{{ t("Datos solo en este navegador. Sin cuenta ni sincronización.") }}</p></footer>
      </main>
    </div>

    <dialog ref="dialog" class="modal" aria-labelledby="modal-title" @cancel.prevent="closeModal" @close="modal=null">
      <div class="modal-header"><div><p class="eyebrow">{{ modal==='detail'?t("TU PRODUCTO"):t("MI DESPENSA") }}</p><h2 id="modal-title">{{ modalTitle }}</h2></div><button class="icon-button" type="button" :disabled="busy" :aria-label="t('Cerrar ventana')" @click="closeModal"><PhX :size="23" /></button></div>
      <template v-if="modal==='detail'&&selected"><div class="detail-summary"><ProductIcon :name="resolveProductIcon(selected)" :size="38" /><span>{{ t(selected.category) }} · {{ t(selected.unit) }}</span><strong>{{ productStock(state,selected.id) }} <small>{{ t(selected.unit) }}</small></strong></div><button class="text-button change-icon" @click="openIcon(selected)">{{ t('Cambiar icono') }}</button><div class="detail-heading"><h3>{{ t("Lotes") }}</h3><button class="text-button" @click="openBatch(selected)"><PhPlus :size="17" />{{ t("Nuevo lote") }}</button></div><p v-if="!batches.length" class="help-text">{{ t("Aún no hay lotes. Añade el primero para registrar existencias.") }}</p><article v-for="batch in batches" :key="batch.id" class="batch-card"><div class="batch-heading"><h4>{{ batchLabel(batch) }}</h4><strong>{{ stock(state,batch.id) }} {{ t(selected.unit) }}</strong></div><p>{{ zoneLabel(batch.location) }} · {{ dateLabel(batch.date) }}</p><p v-if="batch.notes" class="batch-notes">{{ batch.notes }}</p><div class="batch-actions"><button class="text-button" @click="openMovement(selected,'entrada',batch.id)">{{ t("Añadir") }}</button><button class="text-button" :disabled="stock(state,batch.id)===0" @click="openMovement(selected,'consumo',batch.id)">{{ t("Consumir") }}</button><button class="text-button muted" @click="openMovement(selected,'ajuste',batch.id)">{{ t("Corregir recuento") }}</button></div></article><p class="help-text">{{ t("Las fechas son informativas y no garantizan la seguridad de un alimento.") }}</p></template>
      <form v-else-if="modal" @submit.prevent="save"><fieldset :disabled="busy">
        <template v-if="modal==='icon'"><ProductIconPicker v-model="form.icon" :options="iconOptions" :label="t('Icono del producto')" :help="t('Automático elige según el nombre y la unidad. Puedes cambiarlo cuando quieras.')" /></template>
        <template v-if="modal==='product'"><ProductIconPicker v-model="form.icon" :options="iconOptions" :label="t('Icono del producto')" :help="t('Automático elige según el nombre y la unidad. Puedes cambiarlo cuando quieras.')" /><label>{{ t("Nombre del producto") }}<input v-model="form.name" required maxlength="80" :placeholder="t('Ej. Tomate triturado')" /></label><div class="form-row"><label>{{ t("Categoría") }}<select v-model="form.category"><option v-for="item in categories" :key="item" :value="item">{{ t(item) }}</option></select></label><label>{{ t("Unidad") }}<select v-model="form.unit"><option v-for="item in units" :key="item" :value="item">{{ t(item) }}</option></select></label></div><label>{{ t("Cantidad inicial") }} <span class="optional">{{ t("(puedes empezar con 0)") }}</span><input v-model.number="form.quantity" type="number" required min="0" max="1000000" step="1" inputmode="numeric" /></label></template>
        <template v-if="modal==='batch'||(modal==='product'&&form.quantity>0)"><p v-if="modal==='batch'" class="form-product">{{ selected?.name }}</p><label>{{ t("Nombre del lote") }} <span class="optional">{{ t("(opcional)") }}</span><input v-model="form.label" maxlength="80" :placeholder="t('Ej. Tomates de septiembre')" /></label><label v-if="modal==='batch'">{{ t('Cantidad') }} ({{ t(selected?.unit || '') }})<input v-model.number="form.quantity" type="number" required min="1" max="1000000" step="1" inputmode="numeric" /></label><div class="form-row"><label>{{ t("Ubicación") }}<select v-model="form.location"><option v-for="zone in zones" :key="zone.id" :value="zone.id">{{ zoneLabel(zone.id) }}</option></select></label><label>{{ t("Fecha de elaboración") }}<input v-model="form.date" type="date" /></label></div><button type="button" class="text-button inline-zone-toggle" @click="showInlineZone=!showInlineZone;zoneError='';zoneNotice=''">{{ t('Nueva zona') }}<PhPlus :size="16" /></button>
          <div v-if="showInlineZone" class="inline-zone"><label>{{ t('Nombre de la zona') }}<input v-model="zoneName" maxlength="80" :placeholder="t('Ej. Despensa 1, Almacén 2')" @keydown.enter.prevent="createZone(true)" /></label><button type="button" class="button secondary" @click="createZone(true)">{{ t('Crear zona') }}</button></div>
          <p v-if="zoneError" class="alert error" role="alert">{{ t(zoneError) }}</p><p v-if="zoneNotice" class="notice" role="status">{{ t(zoneNotice) }}</p>
          <label>{{ t("Notas") }} <span class="optional">{{ t("(opcional)") }}</span><textarea v-model="form.notes" maxlength="400" rows="3" :placeholder="t('Lo que te gustaría recordar de esta tanda…')" /></label></template>
        <template v-if="modal==='movement'"><p class="form-product">{{ selected?.name }}</p><label>{{ t("Lote") }}<select v-model="form.batchId" required @change="form.movement==='ajuste'&&(form.quantity=currentStock)"><option v-for="batch in availableBatches" :key="batch.id" :value="batch.id">{{ batchLabel(batch) }} · {{ stock(state,batch.id) }} {{ t(selected?.unit || '') }} · {{ zoneLabel(batch.location) }}</option></select></label><p class="stock-hint">{{ t("Ahora tienes") }} <strong>{{ currentStock }} {{ t(selected?.unit || '') }}</strong> {{ t("en este lote.") }}</p><label>{{ form.movement==='ajuste'?t("Cantidad real que hay en el lote"):form.movement==='consumo'?t("¿Cuánto has utilizado?"):t("¿Cuánto quieres añadir?") }}<input v-model.number="form.quantity" type="number" required :min="form.movement==='ajuste'?0:1" :max="form.movement==='consumo'?currentStock:1000000" step="1" inputmode="numeric" /></label><label>{{ form.movement==='ajuste'?t("Motivo de la corrección"):t("Nota") }}<span v-if="form.movement!=='ajuste'" class="optional"> {{ t("(opcional)") }}</span><input v-model="form.reason" :required="form.movement==='ajuste'" maxlength="180" :placeholder="form.movement==='ajuste'?t('Ej. Recuento manual de la despensa'):t('Ej. Para la comida de hoy')" /></label><button v-if="form.movement==='entrada'&&selected" type="button" class="text-button" @click="openBatch(selected)"><PhPlus :size="16" />{{ t("Es una tanda nueva: crear otro lote") }}</button></template>
        <template v-if="modal==='reset'"><p class="body-text">{{ t("Se eliminarán los productos y movimientos de ejemplo, incluidos los cambios que hayas hecho mientras probabas. Tu despensa quedará vacía para añadir tus propios productos.") }}</p></template>
        <p v-if="formError" class="alert error" role="alert">{{ t(formError) }}</p><div class="form-actions"><button type="button" class="button secondary" @click="closeModal">{{ t("Cancelar") }}</button><button type="submit" class="button primary">{{ busy?t("Guardando…"):modal==='reset'?t("Empezar desde cero"):t("Guardar") }}<PhCheck :size="18" /></button></div>
      </fieldset></form>
    </dialog>
  </div>
</template>
